import { createKvServer } from './server.ts';

function parsePort(arg: string | undefined): number {
  const port = Number(arg);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    console.error('usage: app <port>');
    process.exit(2);
  }
  return port;
}

const port = parsePort(process.argv[2]);
const server = createKvServer();
server.on('error', (err) => {
  console.error(`server error: ${err.message}`);
  process.exit(1);
});
server.listen({ port, host: '127.0.0.1', backlog: 1024 });

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close();
    server.closeAllConnections();
    process.exit(0);
  });
}

import http, { type IncomingMessage, type ServerResponse } from 'node:http';
import { KvStore } from './store.ts';

export const MAX_VALUE_BYTES = 1024 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const KV_PREFIX = '/kv/';

class HttpError extends Error {
  readonly status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

function send(res: ServerResponse, status: number, body?: string | Buffer, contentType?: string): void {
  if (status === 204 || body === undefined) {
    res.writeHead(status, status === 204 ? {} : { 'Content-Length': 0 });
    res.end();
    return;
  }
  const payload = typeof body === 'string' ? Buffer.from(body) : body;
  res.writeHead(status, {
    'Content-Type': contentType ?? 'application/octet-stream',
    'Content-Length': payload.length,
  });
  res.end(payload);
}

function methodNotAllowed(res: ServerResponse, allowed: readonly string[]): void {
  res.setHeader('Allow', allowed.join(', '));
  send(res, 405, 'method not allowed\n', 'text/plain; charset=utf-8');
}

async function readBody(req: IncomingMessage, limit: number): Promise<Buffer> {
  const declared = Number(req.headers['content-length'] ?? 0);
  if (declared > limit) throw new HttpError(413, 'value too large');
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req as AsyncIterable<Buffer>) {
    size += chunk.length;
    if (size > limit) throw new HttpError(413, 'value too large');
    chunks.push(chunk);
  }
  return Buffer.concat(chunks, size);
}

export function createKvServer(store: KvStore = new KvStore()): http.Server {
  async function handleKey(req: IncomingMessage, res: ServerResponse, key: string): Promise<void> {
    switch (req.method) {
      case 'GET': {
        const value = store.get(key);
        if (value === undefined) send(res, 404, 'not found\n', 'text/plain; charset=utf-8');
        else send(res, 200, value);
        return;
      }
      case 'PUT': {
        const value = await readBody(req, MAX_VALUE_BYTES);
        send(res, store.put(key, value) ? 201 : 200);
        return;
      }
      case 'DELETE':
        if (store.delete(key)) send(res, 204);
        else send(res, 404, 'not found\n', 'text/plain; charset=utf-8');
        return;
      default:
        methodNotAllowed(res, ['GET', 'PUT', 'DELETE']);
    }
  }

  async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const path = req.url ?? '/';
    if (path === '/health') {
      if (req.method === 'GET') send(res, 200, 'ok', 'text/plain; charset=utf-8');
      else methodNotAllowed(res, ['GET']);
      return;
    }
    if (path === '/kv') {
      if (req.method === 'GET') send(res, 200, JSON.stringify(store.keys()), 'application/json');
      else methodNotAllowed(res, ['GET']);
      return;
    }
    if (path.startsWith(KV_PREFIX)) {
      const key = path.slice(KV_PREFIX.length);
      if (!KEY_PATTERN.test(key)) {
        send(res, 400, 'invalid key\n', 'text/plain; charset=utf-8');
        return;
      }
      await handleKey(req, res, key);
      return;
    }
    send(res, 404, 'not found\n', 'text/plain; charset=utf-8');
  }

  const server = http.createServer((req, res) => {
    route(req, res).catch((err: unknown) => {
      const status = err instanceof HttpError ? err.status : 500;
      if (status === 500) console.error(err);
      if (res.headersSent) {
        res.destroy();
        return;
      }
      res.setHeader('Connection', 'close');
      send(res, status, `${err instanceof HttpError ? err.message : 'internal error'}\n`, 'text/plain; charset=utf-8');
      // Stop reading an oversized or broken body; the socket closes after the response.
      req.resume();
    });
  });
  server.maxConnections = 1024;
  return server;
}

/** In-memory key-value store holding raw byte values. */
export class KvStore {
  readonly #data = new Map<string, Buffer>();

  /** Stores `value` under `key`; returns true if the key was newly created. */
  put(key: string, value: Buffer): boolean {
    const created = !this.#data.has(key);
    this.#data.set(key, value);
    return created;
  }

  get(key: string): Buffer | undefined {
    return this.#data.get(key);
  }

  delete(key: string): boolean {
    return this.#data.delete(key);
  }

  /** All keys in ascending order. Keys are ASCII, so code-unit order is byte order. */
  keys(): string[] {
    return [...this.#data.keys()].sort();
  }
}

import { after, before, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';
import { createKvServer, MAX_VALUE_BYTES } from '../src/server.ts';

const server = createKvServer();
let base = '';

before(async () => {
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
after(() => {
  server.closeAllConnections();
  server.close();
});

const req = (method: string, path: string, body?: Uint8Array<ArrayBuffer> | string): Promise<Response> =>
  fetch(base + path, { method, ...(body === undefined ? {} : { body }) });

describe('kvhttp', () => {
  it('health', async () => {
    const res = await req('GET', '/health');
    assert.equal(res.status, 200);
    assert.equal(await res.text(), 'ok');
    assert.equal((await req('POST', '/health')).status, 405);
  });

  it('crud with binary values', async () => {
    const bytes = new Uint8Array([0, 255, 13, 10, 128]);
    assert.equal((await req('PUT', '/kv/bin', bytes)).status, 201);
    assert.equal((await req('PUT', '/kv/bin', bytes)).status, 200);
    const got = await req('GET', '/kv/bin');
    assert.deepEqual(new Uint8Array(await got.arrayBuffer()), bytes);
    assert.equal((await req('DELETE', '/kv/bin')).status, 204);
    assert.equal((await req('GET', '/kv/bin')).status, 404);
    assert.equal((await req('DELETE', '/kv/bin')).status, 404);
  });

  it('empty value and max-size value', async () => {
    assert.equal((await req('PUT', '/kv/empty', '')).status, 201);
    assert.equal(await (await req('GET', '/kv/empty')).text(), '');
    const big = new Uint8Array(MAX_VALUE_BYTES).fill(7);
    assert.equal((await req('PUT', '/kv/big', big)).status, 201);
    assert.equal((await (await req('GET', '/kv/big')).arrayBuffer()).byteLength, MAX_VALUE_BYTES);
  });

  it('lists keys sorted', async () => {
    for (const k of ['zz', 'A', '_x', '-y', '9']) await req('PUT', `/kv/${k}`, '1');
    const res = await req('GET', '/kv');
    assert.match(res.headers.get('content-type') ?? '', /application\/json/);
    const keys = (await res.json()) as string[];
    assert.deepEqual(keys, [...keys].sort());
    assert.equal((await req('DELETE', '/kv')).status, 405);
  });

  it('errors', async () => {
    assert.equal((await req('GET', '/kv/')).status, 400);
    assert.equal((await req('GET', `/kv/${'a'.repeat(65)}`)).status, 400);
    assert.equal((await req('GET', `/kv/${'a'.repeat(64)}`)).status, 404);
    assert.equal((await req('GET', '/kv/a/b')).status, 400);
    assert.equal((await req('GET', '/kv/a.b')).status, 400);
    assert.equal((await req('GET', '/kv/%41')).status, 400);
    assert.equal((await req('GET', '/nope')).status, 404);
    assert.equal((await req('GET', '/')).status, 404);
    assert.equal((await req('PATCH', '/kv/a')).status, 405);
  });

  it('handles concurrent requests', async () => {
    const results = await Promise.all(
      Array.from({ length: 100 }, (_, i) => req('PUT', `/kv/c${i}`, String(i)).then((r) => r.status)),
    );
    assert.ok(results.every((s) => s === 201));
  });
});
